   "tipo": "internacional",
   "genero": "noticia",
   "imagen": "https://imagenes.elpais.com/resizer/v2/VHCQ3UOT6NMHVAGG4RCXMFSD5Q.jpg?auth=3ad83637c33ae393c3439177175562abe81395541a42236c7748d82c7592c50c",
